// === Tab: pixel_magnets ===
var imageScale;
var dotDensity = .1; // higher ratios = more dots
var damping = 0.4;
var kRadiusFactor = 0.5;
var kSpeed = 3.0;
var minDistFactor = 2.5; // area of influence - smaller numbers make rendering go faster
var radiusRatio = 5;
var radiusOffset = 0.1;
var nbrParticles = 12500;
var particlesPerFrame = 8;  
var reference;
var cachedBrightness;


class Particle
{
	constructor(_x, _y)
	{
		this.vx = 0;
		this.vy = 0;
		this.x = _x;
		this.y = _y;
		this.rad = 1;
		this.vrad = 1;
	}
}

var particles = [];

var minRadius, maxRadius, medRadius;

function preload(){
  reference = loadImage("https://openprocessing.org/sketch/1626890/files/me.jpg");
}

function setup()
{
	createCanvas(640, 640);

	var dwidth = reference.width;
	var dheight = reference.height;
	imageScale = width/dwidth;

	cachedBrightness = new Array(reference.width * reference.height);
	for (var y = 0, i = 0; y < reference.height; y++) {
		for (var x = 0; x < reference.width; x++) {
			var index = y * reference.width + x;
			cachedBrightness[index] = red(reference.get(x, y)) / 255;
		}
	}


	fill(0);
	ellipseMode(CENTER);

	var medArea = (width*height)/nbrParticles;
	medRadius = sqrt(medArea/PI);
	minRadius = medRadius;
	maxRadius = medRadius*medRadius*1;
	background(255);
}

function doPhysics()
{
	for (var i = 0; i < particles.length; ++i) {
		var p = particles[i];
		var px = ~~(p.x / imageScale);//~~ = fast round
		var py = ~~(p.y / imageScale);
		if (px >= 0 && px < reference.width && py >= 0 && py < reference.height) {
			var v =  cachedBrightness[py * reference.width + px];
			p.rad = map(v, 0, 1, minRadius, maxRadius);
			p.vrad = radiusOffset + radiusRatio * (1 - v) ;
		}

		p.fx = 0;
		p.fy = 0;
		p.wt = 0;
		p.vx *= damping;
		p.vy *= damping;
	}

	// Particle -> particle interactions
	for (var i = 0; i < particles.length-1; ++i) {
		var p = particles[i];
		for (var j = i+1; j < particles.length; ++j) {
			var pj = particles[j];
			if (i== j || abs(pj.x - p.x) > p.rad*minDistFactor ||
				abs(pj.y - p.y) > p.rad*minDistFactor)
				continue;

			var dx = p.x - pj.x;
			var dy = p.y - pj.y;
			var distance = sqrt(dx*dx+dy*dy);
			var maxDist = (p.rad + pj.rad);

			var diff = maxDist - distance;
			if (diff > 0) {
				var scle = diff/maxDist;
				scle = scle*scle;
				p.wt += scle;
				pj.wt += scle;
				scle = scle*kSpeed/distance;
				p.fx += dx*scle;
				p.fy += dy*scle;
				pj.fx -= dx*scle;
				pj.fy -= dy*scle;
			}
		}
	}

	for (var i = 0; i < particles.length; ++i) {
		var p = particles[i];

		// keep within edges
		var dx, dy, distance, scle, diff;
		var maxDist = p.rad;
		// left edge  
		distance = dx = p.x - 0;    
		dy = 0;
		diff = maxDist - distance;
		if (diff > 0) {
			scle = diff/maxDist;
			scle = scle*scle;
			p.wt += scle;
			scle = scle*kSpeed/distance;
			p.fx += dx*scle;
			p.fy += dy*scle;
		}
		// right edge  
		dx = p.x - width;    
		dy = 0;
		distance = -dx;
		diff = maxDist - distance;
		if (diff > 0) {
			scle = diff/maxDist;
			scle = scle*scle;
			p.wt += scle;
			scle = scle*kSpeed/distance;
			p.fx += dx*scle;
			p.fy += dy*scle;
		}
		// top edge
		distance = dy = p.y - 0;    
		dx = 0;
		diff = maxDist - distance;
		if (diff > 0) {
			scle = diff/maxDist;
			scle = scle*scle;
			p.wt += scle;
			scle = scle*kSpeed/distance;
			p.fx += dx*scle;
			p.fy += dy*scle;
		}
		// bot edge  
		dy = p.y - height;    
		dx = 0;
		distance = -dy;
		diff = maxDist - distance;
		if (diff > 0) {
			scle = diff/maxDist;
			scle = scle*scle;
			p.wt += scle;
			scle = scle*kSpeed/distance;
			p.fx += dx*scle;
			p.fy += dy*scle;
		}
		if (p.wt > 0) {
			p.vx += p.fx/p.wt;
			p.vy += p.fy/p.wt;
		}
		p.x += p.vx;
		p.y += p.vy;
	}
}


function draw()
{
	background(255);
	//if (particles.length % 100 == 0) println(particles.length);

	if (particles.length < nbrParticles) {
		for (var i = 0; i < particlesPerFrame; i++) {
			particles.push(new Particle(random(width), random(height)));
		}
	}


	doPhysics();

	stroke(0);
	//noStroke();
	for (var i = 0; i < particles.length; ++i) {
		//circle(particles[i].x, particles[i].y, particles[i].vrad);
		strokeWeight(particles[i].vrad);
		point(particles[i].x, particles[i].y);
	}
}

